def seed_muscle_volume_landmarks(apps, schema_editor):
    Muscle = apps.get_model("account", "Muscle")
    Landmark = apps.get_model("account", "MuscleVolumeLandmark")
    aliases = {
        "hypertrophy": {
            "beginner": (6, 10, 14), "intermediate": (8, 13, 18),
            "experienced": (10, 15, 20), "unspecified": (8, 13, 18),
        },
        "strength": {
            "beginner": (3, 5, 8), "intermediate": (4, 7, 10),
            "experienced": (5, 8, 12), "unspecified": (4, 7, 10),
        },
        "sport_performance": {
            "beginner": (3, 5, 8), "intermediate": (4, 7, 10),
            "experienced": (5, 8, 12), "unspecified": (4, 7, 10),
        },
    }
    general = {
        "beginner": (4, 8, 12), "intermediate": (6, 10, 14),
        "experienced": (6, 11, 16), "unspecified": (6, 10, 14),
    }
    goals = (
        "general_fitness", "strength", "hypertrophy", "endurance",
        "mobility", "body_composition", "sport_performance",
    )
    bands = ("beginner", "intermediate", "experienced", "unspecified")
    rows = []
    for muscle_id in Muscle.objects.values_list("pk", flat=True).iterator():
        for goal in goals:
            for band in bands:
                mev, mav, mrv = aliases.get(goal, general)[band]
                rows.append(Landmark(
                    muscle_id=muscle_id,
                    training_goal=goal,
                    experience_band=band,
                    mev=mev,
                    mav=mav,
                    mrv=mrv,
                ))
    Landmark.objects.bulk_create(rows, ignore_conflicts=True)


